import { Component } from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from 'src/app/service/auth.service';
import { RegisterInitiate } from '../../Models/RegisterInitiate';

@Component({
  selector: 'app-otp',
  templateUrl: './otp.component.html',
  styleUrls: ['./otp.component.css']
})
export class OtpComponent {

  constructor(private router: Router, private service: AuthService, private fb: FormBuilder) {}

  role: 'JOBSEEKER' | 'COMPANY' = 'JOBSEEKER';
  step: 'DETAILS' | 'OTP' = 'DETAILS';

  submitting = false;
  errorMessage = '';
  infoMessage = '';

  detailsForm = this.fb.group({
    firstName: [''],
    lastName: [''],
    companyName: [''],
    website: [''],
    industry: [''],
    description: [''],
    skills: [''],
    location: ['', Validators.required],
    email: ['', [Validators.required, Validators.email]],
    password: ['', [Validators.required, Validators.minLength(6)]],
    confirmPassword: ['', Validators.required]
  });

  otpForm = this.fb.group({
    otp: ['', [Validators.required, Validators.minLength(6), Validators.maxLength(6)]]
  });

  selectRole(role: 'JOBSEEKER' | 'COMPANY') {
    this.role = role;
  }

  submitDetails() {
    this.errorMessage = '';

    if (this.detailsForm.invalid) {
      this.detailsForm.markAllAsTouched();
      this.errorMessage = 'Please fill all required fields.';
      return;
    }

    if (this.detailsForm.value.password !== this.detailsForm.value.confirmPassword) {
      this.errorMessage = 'Password and confirm password do not match.';
      return;
    }

    const dto: RegisterInitiate = {
      role: this.role,
      email: this.detailsForm.value.email!,
      password: this.detailsForm.value.password!,
      confirmPassword: this.detailsForm.value.confirmPassword!,
      firstName: this.detailsForm.value.firstName || undefined,
      lastName: this.detailsForm.value.lastName || undefined,
      location: this.detailsForm.value.location || undefined,
      skills: this.role === 'JOBSEEKER'
        ? (this.detailsForm.value.skills || '')
            .split(',')
            .map(skill => skill.trim())
            .filter(skill => skill !== '')
        : undefined,
      companyName: this.detailsForm.value.companyName || undefined,
      website: this.detailsForm.value.website || undefined,
      description: this.detailsForm.value.description || undefined,
      industry: this.detailsForm.value.industry || undefined
    };

    this.submitting = true;

    this.service.registerInitiate(dto).subscribe({
      next: (res: any) => {
        this.submitting = false;
        this.infoMessage = res?.message ?? 'OTP sent to your email.';
        this.step = 'OTP';
      },
      error: (err) => {
        this.submitting = false;
        this.errorMessage = err.error?.message ?? 'Could not start registration. Please try again.';
      }
    });
  }

  verify() {
    this.errorMessage = '';

    if (this.otpForm.invalid) {
      this.otpForm.markAllAsTouched();
      this.errorMessage = 'Enter the 6-digit OTP sent to your email.';
      return;
    }

    this.submitting = true;

    this.service.verifyOtp({
      email: this.detailsForm.value.email!,
      otp: this.otpForm.value.otp!
    }).subscribe({
      next: (res: any) => {
        this.submitting = false;

        localStorage.setItem('token', res.token);
        localStorage.setItem('role', res.role);
        localStorage.setItem('id', res.id);

        alert('Account verified and created successfully!');

        if (res.role === 'COMPANY') {
          this.router.navigate(['/company/company-dashboard']);
        } else {
          this.router.navigate(['/seeker/jobseeker-dashboard']);
        }
      },
      error: (err) => {
        this.submitting = false;
        this.errorMessage = err.error?.message ?? 'Invalid or expired OTP.';
      }
    });
  }

  resend() {
    this.errorMessage = '';
    this.infoMessage = '';

    this.service.resendOtp(this.detailsForm.value.email!).subscribe({
      next: (res: any) => this.infoMessage = res?.message ?? 'OTP resent to your email.',
      error: (err) => this.errorMessage = err.error?.message ?? 'Could not resend OTP.'
    });
  }

  backToDetails() {
    this.step = 'DETAILS';
    this.errorMessage = '';
    this.infoMessage = '';
  }
}
<div class="page">
<app-header variant="guest"></app-header>

<div class="auth-wrap">
  <div class="auth-card" *ngIf="step === 'DETAILS'">
    <h2>Create your account (OTP verified)</h2>
    <p class="muted" style="font-size:13px;margin-bottom:14px;">We'll email you a 6-digit code to confirm it's really you.</p>

    <div class="filter-group">
      <span class="lbl">I am a&hellip;</span>
      <span class="chip-choice" [class.selected]="role === 'JOBSEEKER'" (click)="selectRole('JOBSEEKER')">Job Seeker</span>
      <span class="chip-choice" [class.selected]="role === 'COMPANY'" (click)="selectRole('COMPANY')">Company</span>
    </div>

    <form [formGroup]="detailsForm" (ngSubmit)="submitDetails()">
      <ng-container *ngIf="role === 'JOBSEEKER'">
        <div class="card-row">
          <div class="field"><label>First name</label><input formControlName="firstName" placeholder="Aditi"></div>
          <div class="field"><label>Last name</label><input formControlName="lastName" placeholder="Menon"></div>
        </div>
        <div class="field"><label>Primary skills</label><input formControlName="skills" placeholder="Java, React"></div>
      </ng-container>

      <ng-container *ngIf="role === 'COMPANY'">
        <div class="field"><label>Company name</label><input formControlName="companyName" placeholder="Nimbus Cloud"></div>
        <div class="field"><label>Website</label><input formControlName="website" placeholder="nimbuscloud.io"></div>
        <div class="field"><label>Industry</label><input formControlName="industry" placeholder="Software"></div>
        <div class="field"><label>Description</label><textarea formControlName="description" placeholder="What does the company do?"></textarea></div>
      </ng-container>

      <div class="field"><label>Email</label><input formControlName="email" type="email" placeholder="you@email.com"></div>
      <div class="field"><label>Location</label><input formControlName="location" placeholder="Kochi, IN"></div>
      <div class="card-row">
        <div class="field"><label>Password</label><input formControlName="password" type="password" placeholder="&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;"></div>
        <div class="field"><label>Confirm password</label><input formControlName="confirmPassword" type="password" placeholder="&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;"></div>
      </div>

      <p class="muted" style="color:var(--rose);font-size:13px;margin-bottom:10px;" *ngIf="errorMessage">{{ errorMessage }}</p>

      <button class="btn btn-primary btn-block" type="submit" [disabled]="submitting">{{ submitting ? 'Sending OTP…' : 'Send OTP' }}</button>
    </form>

    <p class="muted" style="font-size:13px;margin-top:14px;">Prefer the regular sign up? <a routerLink="/auth/register">Go back</a></p>
  </div>

  <div class="auth-card" *ngIf="step === 'OTP'">
    <h2>Verify your email</h2>
    <p class="muted" style="font-size:13px;margin-bottom:14px;">Enter the 6-digit code we sent to {{ detailsForm.value.email }}.</p>

    <form [formGroup]="otpForm" (ngSubmit)="verify()">
      <div class="field"><label>OTP</label><input formControlName="otp" maxlength="6" placeholder="482913"></div>

      <p class="muted" style="font-size:13px;margin-bottom:10px;" *ngIf="infoMessage">{{ infoMessage }}</p>
      <p class="muted" style="color:var(--rose);font-size:13px;margin-bottom:10px;" *ngIf="errorMessage">{{ errorMessage }}</p>

      <button class="btn btn-primary btn-block" type="submit" [disabled]="submitting">{{ submitting ? 'Verifying…' : 'Verify & create account' }}</button>
    </form>

    <div style="display:flex;justify-content:space-between;margin-top:14px;">
      <a (click)="backToDetails()" style="cursor:pointer;font-size:13px;">&larr; Edit details</a>
      <a (click)="resend()" style="cursor:pointer;font-size:13px;">Resend OTP</a>
    </div>
  </div>
</div>

<app-footer></app-footer>
</div>
